&lt;li&gt;
&lt;p id=&quot;p-rc_ed609c6a5ee7893e-250&quot; data-path-to-node=&quot;6,0,0&quot;&gt;&lt;span data-path-to-node=&quot;6,0,0,0&quot;&gt;Responsible for building and maintaining the core data warehouse that powers analytics, reporting, machine learning, and partner data products&lt;/span&gt;&lt;span data-path-to-node=&quot;6,0,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;6,0,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
